fn count_digits(text: &Vec<char>) -> usize {
    // Base case: if the vector is empty, return 0
    if text.is_empty() {
        return 0;
    }
    
    // Check the last character
    let last_char = text[text.len() - 1];
    // Count the last character if it's a digit, then recurse on the rest of the vector
    let count = if last_char >= '0' && last_char <= '9' {
        1
    } else {
        0
    };
    
    // Recur with the vector excluding the last character
    count + count_digits(&text[..text.len() - 1].to_vec())
}